async function fresh(provider:'CORE'|'MCP'='CORE',destination?:Record<string,unknown>,readBacks?:(gateway:Gateway)=>CertifiedReadBacks){
 const ctx={tenantId:randomUUID(),actorId:randomUUID()};await admin.query("INSERT INTO tenants(tenant_id,id,corp_id,name,status) VALUES($1,$1,$1::uuid::text,'synthetic controls','ACTIVE')",[ctx.tenantId]);await admin.query("INSERT INTO users(tenant_id,id,external_user_id,display_name,status) VALUES($1,$2,$2::uuid::text,'synthetic requester','ACTIVE')",[ctx.tenantId,ctx.actorId]);
 const task=await new TaskStore(appDb).create(ctx,'synthetic control workflow',randomUUID()),lease=(await store.acquire(ctx,task.runId,'control-setup'))!,gateway=new Gateway(store),id='synthetic.controls.write',name=toolName(id,'1.0.0'),args={note:'PRIVATE_APPROVAL_INPUT_SENTINEL'};let effects=0;
 const capability:Capability={...syntheticResultContract,connectorId:provider==='MCP'?'synthetic-mcp-A':'CORE',id,version:'1.0.0',risk:'SHARED_WRITE',provider,bindingHash:hash('synthetic controls reviewed binding'),state:'READY',schema:z.object({note:z.string()}).strict(),jsonSchema:{type:'object',properties:{note:{type:'string'}},required:['note'],additionalProperties:false},description:'Synthetic verified write to isolated PostgreSQL',resource:(_a,l)=>l.taskId,approvalPreview:a=>({operation:'Synthetic isolated database write',noteDigest:hash((a as typeof args).note)}),operationAudience:(_a,l)=>destination??l.audience,execute:async(a,{principal,lease,actionKey})=>{effects++;const receipt=randomUUID();await db.scope(principal,c=>c.query("INSERT INTO outbox(tenant_id,id,owner_id,kind,aggregate_id,payload_ref,dedup_key,published_at) VALUES($1,$2,$3,'SYNTHETIC_CONTROL_WRITE',$4,$5,$6,now())",[principal.tenantId,receipt,principal.actorId,lease.runId,JSON.stringify(a),actionKey]));return {status:'OK',data:{receipt},evidenceIds:[receipt],completeness:'COMPLETE'};},verify:async(r,_a,{principal})=>{const receipt=(r.data as {receipt:string}).receipt,q=await db.scope(principal,c=>c.query("SELECT id FROM outbox WHERE id=$1 AND kind='SYNTHETIC_CONTROL_WRITE'",[receipt]));return {...r,verification:{state:q.rowCount?'VERIFIED':'MISMATCH',method:'SYNTHETIC_REAL_POSTGRES_READ_BACK'}};}};
 if(provider==='MCP'){await admin.query("INSERT INTO capability_bindings(tenant_id,id,logical_id,semantic_version,provider_binding,schema_hash,risk,state) VALUES($1,$2,$3,'1.0.0','{}',$4,'SHARED_WRITE','READY')",[ctx.tenantId,randomUUID(),id,capability.bindingHash]);await admin.query("INSERT INTO resource_grants(tenant_id,id,actor_id,capability_id,resource_id,audience_kind,audience_id,classification_ceiling,expires_at) VALUES($1,$2,$3,$4,$5,'PRIVATE_USER',$3::uuid::text,'INTERNAL',now()+interval '1 hour')",[ctx.tenantId,randomUUID(),ctx.actorId,id,task.taskId]);}
 if(destination?.['kind']==='GROUP')await admin.query("INSERT INTO resource_grants(tenant_id,id,actor_id,capability_id,resource_id,audience_kind,audience_id,membership_version,classification_ceiling,expires_at) VALUES($1,$2,$3,$4,$5,'GROUP',$6,$7,'INTERNAL',now()+interval '1 hour')",[ctx.tenantId,randomUUID(),ctx.actorId,id,task.taskId,destination['targetId'],destination['membershipVersion']]);
 gateway.register(capability);expect((await gateway.execute(ctx,lease,name,args,AbortSignal.timeout(10000))).status).toBe('NEEDS_APPROVAL');const action=(await db.scope(ctx,c=>c.query('SELECT * FROM tool_actions WHERE run_id=$1',[task.runId]))).rows[0];const api=await approvalFixture(admin,appDb,store,ctx,action.id as string,undefined,readBacks?.(gateway));apps.push(api.app);
 return {ctx,...task,lease,gateway,capability,name,args,action,api,effects:()=>effects};
}
